from bisect import bisect_left


def length_of_lis(nums):
    # tails[k] is the smallest value an increasing subsequence of length k + 1 can end with
    tails = []
    for x in nums:
        i = bisect_left(tails, x)       # first tail >= x; bisect_left keeps the subsequence strictly increasing
        if i == len(tails):
            tails.append(x)             # x extends the longest subsequence found so far
        else:
            tails[i] = x                # a smaller ending is never worse, so replace it
    return len(tails)
